import { TestDriver } from './testDefinition';
import { describe, test, expect } from '@eip/testing';
describe('IBAN validiation', () => {
    test('ValidIban', () => {
        let testInvocation = TestDriver.createTest()
            .startWith('transform')
            .stopAfter('transform')
            .processorAttributes('restConsumer', a => a.attributes({
            "body": {
                "bank_data": {
                    "account": "0532013000",
                    "address": "Venloer Str. 288",
                    "bank": "Commerzbank",
                    "bank_code": "37040044",
                    "bic": "COBADEFFXXX",
                    "branch": null,
                    "branch_code": "",
                    "city": "Köln",
                    "country": "Germany",
                    "country_iso": "DE",
                    "email": null,
                    "fax": null,
                    "phone": null,
                    "state": null,
                    "www": null,
                    "zip": "50447"
                },
                "errors": [],
                "sepa_data": {
                    "B2B": "YES",
                    "COR1": "YES",
                    "SCC": "YES",
                    "SCT": "YES",
                    "SDD": "YES"
                },
                "validations": {
                    "account": {
                        "code": "002",
                        "message": "Account Number check digit is correct"
                    },
                    "chars": {
                        "code": "006",
                        "message": "IBAN does not contain illegal characters"
                    },
                    "country_support": {
                        "code": "007",
                        "message": "Country supports IBAN standard"
                    },
                    "iban": {
                        "code": "001",
                        "message": "IBAN Check digit is correct"
                    },
                    "length": {
                        "code": "003",
                        "message": "IBAN Length is correct"
                    },
                    "structure": {
                        "code": "005",
                        "message": "IBAN structure is correct"
                    }
                }
            },
            "cookies": {},
            "statusCode": 200
        }))
            .test();
        let result = testInvocation.processors.transform.result;
        expect(result.valid).toBeTrue;
        expect(result.bic).toBe('COBADEFFXXX');
        expect(result.bankCode).toBe('37040044');
        expect(result.bankName).toBe('Commerzbank');
    });
    test('InvalidIban', () => {
        let testInvocation = TestDriver.createTest()
            .startWith('transform')
            .stopAfter('transform')
            .processorAttributes('restConsumer', a => a.attributes({
            "body": {
                "bank_data": {
                    "account": "0532019000",
                    "address": "",
                    "bank": "",
                    "bank_code": "34040044",
                    "bic": "",
                    "branch": "",
                    "branch_code": "",
                    "city": "",
                    "country": "Germany",
                    "country_iso": "DE",
                    "email": "",
                    "fax": "",
                    "phone": "",
                    "state": "",
                    "www": "",
                    "zip": ""
                },
                "errors": [],
                "sepa_data": {
                    "B2B": "NO",
                    "COR1": "NO",
                    "SCC": "NO",
                    "SCT": "NO",
                    "SDD": "NO"
                },
                "validations": {
                    "account": {
                        "code": "201",
                        "message": "Account Number check digit not correct"
                    },
                    "chars": {
                        "code": "006",
                        "message": "IBAN does not contain illegal characters"
                    },
                    "country_support": {
                        "code": "007",
                        "message": "Country supports IBAN standard"
                    },
                    "iban": {
                        "code": "202",
                        "message": "IBAN Check digit not correct"
                    },
                    "length": {
                        "code": "003",
                        "message": "IBAN Length is correct"
                    },
                    "structure": {
                        "code": "005",
                        "message": "IBAN structure is correct"
                    }
                }
            },
            "cookies": {},
            "statusCode": 200
        }))
            .test();
        expect(testInvocation.outlet).toEqual('Invalid');
    });
    test('404', () => {
        let testInvocation = TestDriver.createTest()
            .startWith('transform')
            .stopAfter('transform')
            .processorAttributes('restConsumer', a => a.attributes({
            "statusCode": 404
        }))
            .test();
        expect(testInvocation.outlet).toEqual('Error');
    });
    test('InvalidAPIKey', () => {
        let testInvocation = TestDriver.createTest()
            .startWith('transform')
            .stopAfter('transform')
            .processorAttributes('restConsumer', a => a.attributes({
            "body": {
                "bank_data": {},
                "errors": [
                    {
                        "code": "301",
                        "message": "API Key is invalid"
                    }
                ],
                "sepa_data": {},
                "validations": {}
            },
            "cookies": {},
            "statusCode": 200
        }))
            .test();
        expect(testInvocation.outlet).toEqual('Error');
        expect(testInvocation.processors.transform.result.displayMessage).toBe('API Key is invalid');
    });
});

